# Writes descriptions.json (App Store description per locale) from the parts below. Run: python3 build.py
# Only features the iOS app has are named. Native speakers have not checked the translations.
import json, collections
HEAD = ['save', 'sum', 'keep', 'follow', 'yours']
def text(t):
    out = [t['intro']]
    for k in HEAD:
        title, *points = t[k]
        out.append(title + '\n' + '\n'.join('• ' + p for p in points))
    out.append(t['setup'])
    if t.get('ui'): out.append(t['ui'])
    return '\n\n'.join(out)
